# A pretend model, so this runs without an API key. It reacts to wording
# a bit like a real one: vague in, vague out.
def fake_llm(prompt):
    if "one sentence" in prompt and "for a 10-year-old" in prompt:
        return "Plants use sunlight to turn air and water into their own food."
    if "one sentence" in prompt:
        return "Photosynthesis converts light energy into chemical energy in chloroplasts."
    return ("Photosynthesis is a complex process. It has light reactions and the "
            "Calvin cycle. Chlorophyll absorbs light. There is a lot more to say...")

# Step 1: define success BEFORE writing the prompt.
def check(answer):
    return {
        "one sentence": answer.count(".") == 1,
        "under 15 words": len(answer.split()) < 15,
        "no jargon": not any(w in answer for w in ["chloroplast", "Calvin", "chemical"]),
    }

# Step 2: draft, test, refine.
prompts = [
    "Explain photosynthesis.",
    "Explain photosynthesis in one sentence.",
    "Explain photosynthesis in one sentence for a 10-year-old.",
]
for version, prompt in enumerate(prompts, start=1):
    results = check(fake_llm(prompt))
    passed = sum(results.values())
    print(f"v{version}: {passed}/3 checks passed  {results}")

# A tiny evaluation: test cases + graders + a score.
def fake_llm(review):
    # Stand-in for a real model call, so this runs anywhere.
    text = review.lower()
    if "love" in text or "great" in text:
        return "positive"
    if "broke" in text or "late" in text:
        return "Negative."
    return "positive"

test_cases = [
    {"input": "I love this blender!", "expected": "positive"},
    {"input": "It broke after a day.", "expected": "negative"},
    {"input": "Shipping was late again.", "expected": "negative"},
    {"input": "It is a blender. It blends.", "expected": "neutral"},
    {"input": "Great value for money.", "expected": "positive"},
]

# Code-based graders: fast, cheap and repeatable.
def exact_match(output, expected):
    return output == expected

def normalized_match(output, expected):
    return output.strip(" .").lower() == expected

for grader in [exact_match, normalized_match]:
    passed = 0
    for case in test_cases:
        output = fake_llm(case["input"])
        ok = grader(output, case["expected"])
        passed += ok
        if not ok and grader is normalized_match:
            print(f"  FAIL: {case['input']!r} -> {output!r}, expected {case['expected']!r}")
    print(f"{grader.__name__}: {passed}/{len(test_cases)} passed")
